const animeDetailsQuery=`query($id:Int){Media(id:$id,type:ANIME){id siteUrl format duration genres trailer{id site} externalLinks{site url type isDisabled} streamingEpisodes{title url site}}}`;
const warmEscape=value=>{const node=document.createElement('span');node.textContent=value||'';return node.innerHTML};
function splitQuoteForTranslation(quote,maxLength=430){const words=(quote||'').trim().split(/\s+/).filter(Boolean);const parts=[];let current='';for(const word of words){const next=current?`${current} ${word}`:word;if(next.length>maxLength&&current){parts.push(current);current=word}else current=next}if(current)parts.push(current);return parts}
async function translateQuote(quote){const parts=splitQuoteForTranslation(quote);if(!parts.length)throw new Error('No quote');const translations=[];for(const part of parts){const url=`https://api.mymemory.translated.net/get?q=${encodeURIComponent(part)}&langpair=en|fr`;const response=await fetch(url);if(!response.ok)throw new Error('Translation unavailable');const data=await response.json();const translated=data.responseData?.translatedText;if(!translated||/query length limit|max allowed query/i.test(translated))throw new Error('Translation unavailable');translations.push(translated)}return translations.join(' ')}
async function setFrenchQuote(){const button=document.querySelector('#quoteButton');button.disabled=true;const label=button.textContent;button.textContent='Traduction…';try{const quoteResponse=await fetch('https://api.animechan.io/v1/quotes/random');if(!quoteResponse.ok)throw new Error();const {data}=await quoteResponse.json();const french=await translateQuote(data.content);document.querySelector('#quoteText').innerHTML=`<span class="translated-quote">« ${warmEscape(french)} »<small>Version originale : “${warmEscape(data.content)}”</small></span>`;document.querySelector('#quoteAuthor').textContent=`— ${data.character.name}, ${data.anime.name} · Traduction automatique`;}catch(error){document.querySelector('#quoteText').textContent='La traduction française est momentanément indisponible.';document.querySelector('#quoteAuthor').textContent='Tu peux réessayer dans quelques instants.';}finally{button.disabled=false;button.textContent=label}}
function playerLink(trailer){if(!trailer?.id)return null;if(trailer.site==='youtube'||trailer.site==='YouTube')return `https://www.youtube.com/watch?v=${encodeURIComponent(trailer.id)}`;return null}
function isWatchLink(link){return /crunchyroll|netflix|prime video|amazon|hulu|disney|hidive|bilibili|wakanim|funimation|youtube/i.test(`${link.site||''} ${link.type||''}`)}
async function enrichAnimeDetail(animeId){try{const response=await fetch('https://graphql.anilist.co',{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({query:animeDetailsQuery,variables:{id:Number(animeId)}})});const payload=await response.json();const anime=payload.data?.Media;if(!anime)return;const detail=document.querySelector('#dialogContent > .detail > div');if(!detail||detail.querySelector('.detail-warm'))return;const trailer=playerLink(anime.trailer);const uniqueLinks=[...(anime.streamingEpisodes||[]).map(x=>({name:x.site||x.title,url:x.url})),...(anime.externalLinks||[]).filter(x=>x.url&&!x.isDisabled&&isWatchLink(x)).map(x=>({name:x.site,url:x.url}))].filter((item,index,array)=>item.url&&array.findIndex(x=>x.url===item.url)===index).slice(0,5);const genres=(anime.genres||[]).slice(0,3).join(', ')||'cet univers';const actions=[trailer?`<a href="${trailer}" target="_blank" rel="noopener">▶ Bande-annonce</a>`:'',anime.siteUrl?`<a class="secondary" href="${anime.siteUrl}" target="_blank" rel="noopener">Fiche AniList ↗</a>`:''].join('');const watch=uniqueLinks.length?`<div class="watch-links">${uniqueLinks.map(link=>`<a href="${warmEscape(link.url)}" target="_blank" rel="noopener">Regarder sur ${warmEscape(link.name)} ↗</a>`).join('')}</div><p class="link-note">Liens externes fournis par AniList — disponibilité selon ton pays.</p>`:`<p class="link-note">Aucun lien légal de visionnage n’est référencé pour le moment dans ta région.</p>`;detail.insertAdjacentHTML('beforeend',`<section class="detail-warm"><h3>Pourquoi il pourrait te plaire</h3><p>Une porte d’entrée dans ${warmEscape(genres)}, à explorer selon ton humeur du moment.</p><div class="detail-actions">${actions}</div>${watch}</section>`)}catch(error){/* Le synopsis et les favoris restent disponibles même si les liens externes ne répondent pas. */}}
document.querySelector('#quoteButton').addEventListener('click',event=>{event.stopImmediatePropagation();setFrenchQuote()},{capture:true});
grid.addEventListener('click',event=>{const card=event.target.closest('.anime-card');if(card)setTimeout(()=>enrichAnimeDetail(card.dataset.id),0)},{capture:true});
grid.addEventListener('keydown',event=>{const card=event.target.closest('.anime-card');if(card&&event.key==='Enter')setTimeout(()=>enrichAnimeDetail(card.dataset.id),0)},{capture:true});
